// Turns tokens.json into the files each app reads. Run from anywhere: node design/tokens/build.mjs
//   --check   write nothing; exit 1 if a generated file is out of date or a contrast rule fails (for CI)
// No dependencies. Outputs:
//   apps/windows/ui/src/system/tokens.generated.css          CSS variables (--w-*), and the Thread palette as .w-thread
//   apps/macos/WhimbrelUI/Sources/WhimbrelUI/Tokens.generated.swift
//   design/tokens/generated/thread.json, thread-high-contrast.json   palettes in the themes/*.json schema
//   skins/palettes/thread.json   the Thread palette (light and dark) as a bundled skin palette
//   skins/thread.json            the Thread skin manifest (hidden unless the redesign flag is on; see docs/ui-redesign/skins.md)
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("../../", import.meta.url));
const T = JSON.parse(readFileSync(`${ROOT}design/tokens/tokens.json`, "utf8"));
const CHECK = process.argv.includes("--check");
const MODES = ["light", "dark", "highContrastLight", "highContrastDark"];
const strip = (group) => Object.fromEntries(Object.entries(group).filter(([key]) => !key.startsWith("$")));
const kebab = (name) => name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
/** A wrapper that forces a mode opts out of every automatic (system-following) rule. */
const FORCED = ":not(.w-mode-light):not(.w-mode-dark):not(.w-mode-hc-light):not(.w-mode-hc-dark)";
const HEADER = "Generated by design/tokens/build.mjs from design/tokens/tokens.json. Do not edit by hand.";

// ---- contrast rules -------------------------------------------------------------------------------------------
const lum = (hex) => {
  const n = parseInt(hex.slice(1), 16);
  const ch = (v) => ((v /= 255) <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  return 0.2126 * ch((n >> 16) & 255) + 0.7152 * ch((n >> 8) & 255) + 0.0722 * ch(n & 255);
};
const ratio = (a, b) => (Math.max(lum(a), lum(b)) + 0.05) / (Math.min(lum(a), lum(b)) + 0.05);

/** Text pairs (4.5:1, or 7:1 in high contrast) and non-text pairs (3:1) every mode must pass. `fixed.x` names a fixed color. */
const TEXT_PAIRS = [
  ["textPrimary", "backgroundPage"], ["textPrimary", "backgroundCard"], ["textSecondary", "backgroundPage"], ["textSecondary", "backgroundCard"],
  ["textPrimary", "selection"], ["textPrimary", "highlight"], ["textOnAccent", "accentPrimary"],
  ["accentPrimary", "backgroundPage"], ["accentPrimary", "backgroundCard"], ["link", "backgroundCard"], ["link", "backgroundPage"],
  ["error", "backgroundCard"], ["warning", "backgroundCard"], ["success", "backgroundCard"],
  ["fixed.onRecording", "fixed.recording"], ["fixed.recording", "backgroundCard"], ["fixed.recording", "backgroundPage"], ["fixed.recording", "fixed.recordingTint"],
  ["fixed.aiInk", "backgroundCard"], ["fixed.aiInk", "backgroundPage"], ["fixed.aiInk", "fixed.aiTint"], ["textPrimary", "fixed.aiTint"],
  ["fixed.paused", "backgroundCard"], ["fixed.paused", "backgroundPage"],
];
const NON_TEXT_PAIRS = [
  ["fixed.focus", "backgroundCard"], ["fixed.focus", "backgroundPage"],
  ["fixed.appBlue", "backgroundCard"], ["fixed.appGreen", "backgroundCard"], ["fixed.appPurple", "backgroundCard"], ["fixed.appAmber", "backgroundCard"],
];
const fixed = strip(T.fixed);
const color = (name, mode) => (name.startsWith("fixed.") ? fixed[name.slice(6)].$value[MODES.indexOf(mode)] : T.palette[mode][name]);
const failures = [];
for (const mode of MODES) {
  const textMin = mode.startsWith("highContrast") ? 7 : 4.5;
  for (const [pairs, min] of [[TEXT_PAIRS, textMin], [NON_TEXT_PAIRS, 3]])
    for (const [fg, bg] of pairs) {
      const r = ratio(color(fg, mode), color(bg, mode));
      if (r < min) failures.push(`${mode}: ${fg} on ${bg} = ${r.toFixed(2)} (needs ${min})`);
    }
}
if (failures.length) {
  console.error(`Contrast rules failed:\n  ${failures.join("\n  ")}`);
  process.exit(1);
}

// ---- CSS ------------------------------------------------------------------------------------------------------
const cssVars = (pairs, indent = "  ") => pairs.map(([name, value]) => `${indent}${name}: ${value};`).join("\n");
const fixedVars = (mode) => Object.entries(fixed).map(([name, token]) => [`--w-color-${kebab(name)}`, token.$value[MODES.indexOf(mode)].toLowerCase()]);
const paletteVars = (mode) => Object.entries(T.palette[mode]).map(([name, value]) => [`--color-${kebab(name)}`, value.toLowerCase()]);
const rem = (px) => `${px / 16}rem`;
const shadow = ([y, blur, alpha]) => (alpha === 0 ? "none" : `0 ${y}px ${blur}px color-mix(in srgb, var(--w-color-scrim) ${Math.round(alpha * 100)}%, transparent)`);
const bezier = (v) => `cubic-bezier(${v.join(", ")})`;

const staticVars = [
  ...Object.entries(strip(T.space)).map(([k, v]) => [`--w-space-${k}`, `${v}px`]),
  ...Object.entries(T.radius.win).map(([k, v]) => [`--w-radius-${k}`, `${v}px`]),
  ...Object.entries(T.type.roles).flatMap(([role, v]) => [
    [`--w-text-${kebab(role)}-size`, rem(v.win[0])],
    [`--w-text-${kebab(role)}-line`, rem(v.win[1])],
    [`--w-text-${kebab(role)}-weight`, String(v.weight)],
  ]),
  ...Object.entries(T.type.family.win).map(([k, v]) => [`--w-font-${k}`, v.replaceAll("'", '"')]),
  ["--w-reading-measure", `${T.type.readingMeasure}ch`],
  ...Object.entries(strip(T.elevation)).map(([k, v]) => [`--w-shadow-${k}`, shadow(v)]),
  ...Object.entries(T.motion.duration.win).map(([k, v]) => [`--w-duration-${k}`, `${v}ms`]),
  ...Object.entries(T.motion.easing).map(([k, v]) => [`--w-ease-${k}`, bezier(v)]),
  ["--w-target", `${T.size.target.win}px`],
  ["--w-sidebar-width", `${T.size.sidebar}px`],
  ["--w-spine-width", `${T.size.spine}px`],
  ["--w-content-max", `${T.size.contentMax}px`],
];

const threadSkinVars = [
  ["--radius", `${T.radius.win.card}px`],
  ["--radius-control", `${T.radius.win.control}px`],
  ["--radius-card", `${T.radius.win.card}px`],
  ["--radius-surface", `${T.radius.win.surface}px`],
  ["--font-body", "var(--w-font-ui)"],
  ["--font-label", "var(--w-font-ui)"],
  ["--font-numerals", "var(--w-font-ui)"],
  ["--font-display", "var(--w-font-ui)"],
  ["--weight-display", "600"],
  ["--border-style", "solid"],
  ["--border-width", "1px"],
  ["--density", "1"],
  ["--caps", "none"],
];

const css = `/* ${HEADER} */

/* Sizes, type, shape and motion. Type sizes are rem, so the Windows text size setting scales them. */
:root {
${cssVars(staticVars)}
}

/* With Reduce Motion nothing moves: every duration is zero. */
@media (prefers-reduced-motion: reduce) {
  :root {
${cssVars(Object.keys(T.motion.duration.win).map((k) => [`--w-duration-${k}`, "0ms"]), "    ")}
  }
}

/* Fixed colors: a skin cannot change these. Light, then dark, then high contrast, following the system
   unless the skin code has forced an appearance (data-theme) or a wrapper forces a mode (.w-mode-*). */
:root, .w-mode-light {
${cssVars(fixedVars("light"))}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${cssVars(fixedVars("dark"), "    ")}
  }
}
:root[data-theme="dark"], .w-mode-dark {
${cssVars(fixedVars("dark"))}
}
@media (prefers-contrast: more) {
  :root {
${cssVars(fixedVars("highContrastLight"), "    ")}
  }
}
@media (prefers-contrast: more) and (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${cssVars(fixedVars("dark").map(([n], i) => [n, fixedVars("highContrastDark")[i][1]]), "    ")}
  }
}
.w-mode-hc-light {
${cssVars(fixedVars("highContrastLight"))}
}
.w-mode-hc-dark {
${cssVars(fixedVars("highContrastDark"))}
}

/* The Thread palette on the 15 skinnable tokens. Opt in with class="w-thread" until Thread is the default. */
.w-thread, .w-thread.w-mode-light {
${cssVars(paletteVars("light"))}
  color-scheme: light;
}
/* Thread's shape and fonts, on the variables a skin sets (skin.ts), so Thread behaves like any other skin. */
.w-thread {
${cssVars(threadSkinVars)}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .w-thread${FORCED}, :root:not([data-theme="light"]).w-thread${FORCED} {
${cssVars(paletteVars("dark"), "    ")}
    color-scheme: dark;
  }
}
:root[data-theme="dark"] .w-thread${FORCED}, .w-thread.w-mode-dark {
${cssVars(paletteVars("dark"))}
  color-scheme: dark;
}
@media (prefers-contrast: more) {
  .w-thread${FORCED} {
${cssVars(paletteVars("highContrastLight"), "    ")}
  }
}
@media (prefers-contrast: more) and (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .w-thread${FORCED} {
${cssVars(paletteVars("highContrastDark"), "    ")}
  }
}
.w-thread.w-mode-hc-light {
${cssVars(paletteVars("highContrastLight"))}
  color-scheme: light;
}
.w-thread.w-mode-hc-dark {
${cssVars(paletteVars("highContrastDark"))}
  color-scheme: dark;
}
`;

// ---- Swift ----------------------------------------------------------------------------------------------------
const hex = (value) => `0x${value.slice(1).toUpperCase()}`;
const swiftPalette = (mode) => `[${Object.entries(T.palette[mode]).map(([k, v]) => `"${k}": ${hex(v)}`).join(", ")}]`;
const swiftWeight = (w) => ({ 400: ".regular", 500: ".medium", 600: ".semibold", 700: ".bold" })[w];
const swift = `// ${HEADER}
// swiftlint:disable all
import SwiftUI

/// Sizes, type, shape and motion for the Thread design system (macOS values).
public enum WTokens {
    public enum Space {
${Object.entries(strip(T.space)).map(([k, v]) => `        public static let ${k}: CGFloat = ${v}`).join("\n")}
    }

    public enum Radius {
${Object.entries(T.radius.mac).map(([k, v]) => `        public static let ${k}: CGFloat = ${v}`).join("\n")}
    }

    /// One type role: point size, line height and weight at the default text size.
    public struct TypeRole: Sendable {
        public let size: CGFloat
        public let lineHeight: CGFloat
        public let weight: Font.Weight
    }

    public enum TypeScale {
${Object.entries(T.type.roles).map(([k, v]) => `        public static let ${k} = TypeRole(size: ${v.mac[0]}, lineHeight: ${v.mac[1]}, weight: ${swiftWeight(v.weight)})`).join("\n")}
        public static let minimumReadable: CGFloat = ${T.type.minimumReadable}
        public static let readingMeasure: Int = ${T.type.readingMeasure}
    }

    /// A shadow: vertical offset, blur radius, and opacity of the scrim color.
    public struct Shadow: Sendable {
        public let y: CGFloat
        public let blur: CGFloat
        public let opacity: Double
    }

    public enum Elevation {
${Object.entries(strip(T.elevation)).map(([k, v]) => `        public static let level${k} = Shadow(y: ${v[0]}, blur: ${v[1]}, opacity: ${v[2]})`).join("\n")}
    }

    public enum Motion {
${Object.entries(T.motion.duration.mac).map(([k, v]) => `        public static let ${k}: Double = ${v / 1000}`).join("\n")}
    }

    public enum Size {
        public static let target: CGFloat = ${T.size.target.mac}
        public static let sidebar: CGFloat = ${T.size.sidebar}
        public static let spine: CGFloat = ${T.size.spine}
        public static let contentMax: CGFloat = ${T.size.contentMax}
    }
}

/// A color a skin cannot change, in its four variants.
public struct WFixedColor: Sendable {
    public let light: UInt32
    public let dark: UInt32
    public let highContrastLight: UInt32
    public let highContrastDark: UInt32
}

public enum WFixed {
${Object.entries(fixed).map(([k, t]) => `    public static let ${k} = WFixedColor(light: ${hex(t.$value[0])}, dark: ${hex(t.$value[1])}, highContrastLight: ${hex(t.$value[2])}, highContrastDark: ${hex(t.$value[3])})`).join("\n")}
}

/// The Thread palette on the 15 skinnable tokens, keyed by the names themes/*.json uses.
public enum WThreadPalette {
${MODES.map((m) => `    public static let ${m}: [String: UInt32] = ${swiftPalette(m)}`).join("\n")}
}
`;

// ---- palette files in the themes/ schema ----------------------------------------------------------------------
const themeFile = (id, name, light, dark) => `${JSON.stringify({ id, name, author: "Whimbrel", light: T.palette[light], dark: T.palette[dark] }, null, 2)}\n`;

// ---- the Thread skin, bundled as data ---------------------------------------------------------------------------
// Same schema as every other skin: no field is added. Icons and voice (with every translation) come from skins/whimbrel.json,
// so Thread keeps whatever strings Whimbrel has. The skin format has one radius for both systems, so the file carries
// the Windows card value; the Mac's 8 / 14 corners for Thread are applied in code when the redesign components draw.
const sortKeys = (value) =>
  Array.isArray(value)
    ? value.map(sortKeys)
    : value && typeof value === "object"
      ? Object.fromEntries(Object.keys(value).sort().map((key) => [key, sortKeys(value[key])]))
      : value;
const WEIGHT_NAMES = { 400: "regular", 500: "medium", 600: "semibold", 700: "bold" };
const face = (role) => `SF Pro/${WEIGHT_NAMES[T.type.roles[role].weight]}`;
const whimbrelSkin = JSON.parse(readFileSync(`${ROOT}skins/whimbrel.json`, "utf8"));
const threadSkin = sortKeys({
  id: "thread",
  name: "Thread",
  author: "Whimbrel",
  palettes: ["thread"],
  // System faces only: SF Pro for display, body, numerals (the time role) and label. No capitals.
  typography: { display: face("title"), body: face("body"), numerals: face("time"), label: face("secondary"), caps: "none" },
  shape: { radius: T.radius.win.card, border: "solid", borderWidth: 1, density: "regular" },
  icons: whimbrelSkin.icons,
  decoration: { headerBand: "none", dividers: "none", texture: "none", imagery: [] },
  voice: whimbrelSkin.voice,
  voiceLocalized: whimbrelSkin.voiceLocalized,
  today: { archetype: "standard", options: { nextMeeting: "card", timeline: "line", labels: "plain", ask: "field", actions: "buttons" } },
  motion: "subtle",
});

const outputs = {
  "apps/windows/ui/src/system/tokens.generated.css": css,
  "apps/macos/WhimbrelUI/Sources/WhimbrelUI/Tokens.generated.swift": swift,
  "design/tokens/generated/thread.json": themeFile("thread", "Thread", "light", "dark"),
  "design/tokens/generated/thread-high-contrast.json": themeFile("thread-high-contrast", "Thread High Contrast", "highContrastLight", "highContrastDark"),
  "skins/palettes/thread.json": themeFile("thread", "Thread", "light", "dark"),
  "skins/thread.json": `${JSON.stringify(threadSkin, null, 2)}\n`,
};

let stale = 0;
for (const [path, text] of Object.entries(outputs)) {
  const full = `${ROOT}${path}`;
  // A Windows checkout may hold these files with CRLF line ends; that is not a stale file.
  const current = existsSync(full) ? readFileSync(full, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === text) continue;
  stale++;
  if (CHECK) console.error(`out of date: ${path}`);
  else {
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, text);
    console.log(`wrote ${path}`);
  }
}
if (CHECK && stale) {
  console.error("Run: node design/tokens/build.mjs");
  process.exit(1);
}
console.log(CHECK ? "tokens are up to date" : `${stale} file(s) written, contrast rules pass`);
